1	'use strict'
2	
3	// Scout: pure perception + chat, no brain, no body cost. The bot already
4	// walks with the player, so every few seconds it looks at the loaded chunks
5	// around itself (mineflayer keeps them in memory — this sees through walls,
6	// including ore underground) and reports new veins in chat.
7	//
8	// Runs at the every-tick seam in index.js regardless of the brain decision,
9	// so it keeps working while the bot is following, fighting, or idle.
10	
11	const ORE_NAMES = [
12	  'diamond_ore',
13	  'deepslate_diamond_ore',
14	  'emerald_ore',
15	  'deepslate_emerald_ore',
16	  'ancient_debris',
17	  'gold_ore',
18	  'deepslate_gold_ore',
19	  'iron_ore',
20	  'deepslate_iron_ore',
21	  'lapis_ore',
22	  'deepslate_lapis_ore',
23	  'redstone_ore',
24	  'deepslate_redstone_ore',
25	]
26	
27	function baseName(name) {
28	  return name.startsWith('deepslate_') ? name.slice('deepslate_'.length) : name
29	}
30	
31	// Report priority: index of the first ORE_NAMES entry that strips to the
32	// same base name, so deepslate variants share their base rank.
33	function rankOf(name) {
34	  const base = baseName(name)
35	  for (let i = 0; i < ORE_NAMES.length; i++) {
36	    if (baseName(ORE_NAMES[i]) === base) return i
37	  }
38	  return ORE_NAMES.length
39	}
40	
41	function keyOf(p) {
42	  return `${p.x},${p.y},${p.z}`
43	}
44	
45	function dist(a, b) {
46	  if (a && typeof a.distanceTo === 'function') return a.distanceTo(b)
47	  if (b && typeof b.distanceTo === 'function') return b.distanceTo(a)
48	  return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z)
49	}
50	
51	function resolveIds(bot, names) {
52	  const byName = (bot.registry && bot.registry.blocksByName) || {}
53	  const ids = []
54	  for (const name of names) {
55	    const entry = byName[name]
56	    // Names missing from the registry are skipped, not fatal.
57	    if (entry && typeof entry.id === 'number') ids.push(entry.id)
58	  }
59	  return ids
60	}
61	
62	// Name -> ore ids for the 'find me <block>' chat command: the exact
63	// name, plus every registry block containing <base>_ore (covers
64	// deepslate_* and nether_* variants). Registry names that are missing
65	// are skipped, not fatal.
66	function resolveBlockIds(bot, blockName) {
67	  const byName = (bot.registry && bot.registry.blocksByName) || {}
68	  const base = blockName.endsWith('_ore') ? blockName.slice(0, -'_ore'.length) : blockName
69	  const ids = []
70	  const exact = byName[blockName]
71	  if (exact && typeof exact.id === 'number') ids.push(exact.id)
72	  const pattern = `${base}_ore`
73	  for (const name of Object.keys(byName)) {
74	    if (name.includes(pattern)) {
75	      const entry = byName[name]
76	      if (entry && typeof entry.id === 'number' && !ids.includes(entry.id)) ids.push(entry.id)
77	    }
78	  }
79	  return ids
80	}
81	
82	// Scan helper, exported for the 'find me <block>' chat command:
83	// block name -> nearest loaded position; null when the name resolves but
84	// nothing is nearby; 'unknown' when the name matches no block at all so the
85	// caller can answer 'unknown block'.
86	function findNearestBlock(bot, blockName, radius = 48) {
87	  const ids = resolveBlockIds(bot, blockName)
88	  if (ids.length === 0) return 'unknown'
89	  let found = null
90	  try {
91	    found = bot.findBlocks({ matching: ids, maxDistance: radius, count: 64 })
92	  } catch {
93	    return null
94	  }
95	  if (!found || found.length === 0) return null
96	  const origin = bot.entity && bot.entity.position
97	  let best = found[0]
98	  if (origin) {
99	    for (const p of found) {
100	      if (dist(p, origin) < dist(best, origin)) best = p
101	    }
102	  }
103	  return best
104	}
105	
106	function findNearest(bot, blockName, radius = 48) {
107	  const p = findNearestBlock(bot, blockName, radius)
108	  if (p === 'unknown') return 'unknown'
109	  if (!p) return null
110	  const origin = bot.entity && bot.entity.position
111	  const distance = origin ? Math.round(dist(p, origin)) : 0
112	  let name = blockName
113	  try {
114	    const block = bot.blockAt && bot.blockAt(p)
115	    if (block && block.name) name = block.name
116	  } catch {
117	    name = blockName
118	  }
119	  return { name, position: p, distance }
120	}
121	
122	function makeScout(bot, { everyMs = 5000, radius = 16, say = bot.chat, now = () => Date.now(), maxSeen = 5000 } = {}) {
123	  const oreIds = resolveIds(bot, ORE_NAMES)
124	  const seen = new Set()
125	  let lastScan = 0
126	
127	  function tick() {
128	    const t = now()
129	    if (t - lastScan < everyMs) return
130	    lastScan = t
131	    let found = []
132	    try {
133	      found = bot.findBlocks({ matching: oreIds, maxDistance: radius, count: 64 }) || []
134	    } catch {
135	      return
136	    }
137	    const fresh = new Map() // base ore name -> new positions
138	    for (const p of found) {
139	      const key = keyOf(p)
140	      if (seen.has(key)) continue
141	      seen.add(key)
142	      let name = null
143	      try {
144	        const block = bot.blockAt(p)
145	        name = block && block.name
146	      } catch {
147	        name = null
148	      }
149	      if (!name) continue
150	      const base = baseName(name)
151	      if (!fresh.has(base)) fresh.set(base, [])
152	      fresh.get(base).push(p)
153	    }
154	    // ponytail: bounded memory, LRU if it ever matters.
155	    if (seen.size > maxSeen) seen.clear()
156	    const names = [...fresh.keys()].sort((a, b) => rankOf(a) - rankOf(b)).slice(0, 3)
157	    const origin = bot.entity && bot.entity.position
158	    for (const name of names) {
159	      const spots = fresh.get(name)
160	      let nearest = spots[0]
161	      if (origin) {
162	        for (const p of spots) {
163	          if (dist(p, origin) < dist(nearest, origin)) nearest = p
164	        }
165	      }
166	      const line = `${name} x${spots.length} at ${nearest.x} ${nearest.y} ${nearest.z}`
167	      say.call(bot, line)
168	      console.log(`scout ${line}`)
169	    }
170	  }
171	
172	  return { tick }
173	}
174	
175	module.exports = { makeScout, findNearestBlock, findNearest, resolveBlockIds, ORE_NAMES }
176

